/**
 * 분야마다 관련 있는 영역. 코드 앞부분(예: "4과13" → [4과13-xx], "9역" → 중학교 역사 전체)으로 고른다.
 * 학년군을 고를 때 이 영역의 성취기준만 프롬프트에 넣어 너무 길어지지 않게 한다.
 */
const FIELD_AREAS: Record<LibraryField, string[]> = {
  // 우주·과학: 천체·지구의 운동, 힘·빛·소리·열·전기 같은 물리 현상, 과학기술과 진로
  space: [
    "4과01", "4과07", "4과09", "4과13", "4과15",
    "6과02", "6과07", "6과10", "6과12", "6과13", "6과15", "6과16",
    "9과01", "9과05", "9과06", "9과07", "9과10", "9과14", "9과15", "9과19", "9과23",
  ],
  // 지구·환경: 땅·바다·날씨·기후, 생물과 생태계, 자원·재해, 환경을 다루는 사회 지리
  earth: [
    "4과02", "4과03", "4과06", "4과10", "4과11", "4과14", "4과16",
    "6과01", "6과06", "6과08", "6과09", "6과14",
    "9과02", "9과09", "9과17", "9과18", "9과22",
    "4사10", "6사02", "6사10", "6사12",
    "9사(지리)06", "9사(지리)08", "9사(지리)12",
  ],
  // 경제: 사회과 경제 영역과 산업·자원·무역을 다루는 지리 영역
  economy: [
    "4사07", "6사11",
    "9사(일사)08", "9사(일사)09", "9사(일사)10",
    "9사(지리)02", "9사(지리)05", "9사(지리)12",
  ],
  // 역사·문화: 사회과 역사·문화 영역, 중학교 역사, 우리말과 글을 다루는 국어 문법 영역
  culture: [
    "4사02", "4사03", "4사04", "4사06",
    "6사04", "6사05", "6사06", "6사07",
    "9사(일사)02", "9역",
    "4국04", "6국04", "9국04",
  ],
};

export function standardsForField(field: LibraryField): CurriculumStandard[] {
  const prefixes = FIELD_AREAS[field].map((p) => `[${p}`);
  return CURRICULUM_STANDARDS.filter((s) => prefixes.some((p) => s.code.startsWith(p)));
}

const GRADE_SHORT: Record<GradeLevel, string> = { elem34: "초3~4", elem56: "초5~6", middle: "중학교" };

/** 예) "초5~6 과학 '혼합물의 분리' [6과05-01]" */
export function describeStandard(s: CurriculumStandard) {
  return `${GRADE_SHORT[s.grade]} ${s.subject} '${s.area}' ${s.code}`;
}
